    ///
    /// `--replace-pre-with-code-fences` is the former name and still works. It was always a
    /// misnomer: this has never looked at `<pre>` tags.
    #[usage(
        long = "indented-blocks-to-code-fences",
        alias = "replace-pre-with-code-fences"
    )]
