impl usage_rs::Run for Markdown {
    type Output = usage::miette::Result<()>;

    fn run(self) -> Self::Output {
        // The banner belongs to every generated document, so build it in one place rather
        // than once per output path.
        let render = |md: &str| {
            format!(
                "<!-- @generated by usage-cli from usage spec -->\n{}\n",
                md.trim()
            )
        };
        // File-only, deliberately: every path this receives is a join onto `--out-dir`, so a
        // `-` meaning stdout cannot turn up here.
        let write = |path: &PathBuf, md: &str| -> usage::miette::Result<()> {
            eprintln!("writing to {}", path.display());
            super::write_file(path, render(md))?;
            Ok(())
        };
        let spec = select_view(parse_file_or_stdin(&self.file)?, self.view.as_deref())?;
        let mut ctx = MarkdownRenderer::new(spec.clone())
            .with_html_encode(self.html_encode)
            .with_indented_blocks_to_code_fences(self.indented_blocks_to_code_fences);
        for value in &self.template {
            let Some((name, path)) = value.split_once('=') else {
                usage::miette::bail!("invalid template `{value}`; expected NAME=PATH");
            };
            let template = match name {
                "spec" => MarkdownTemplate::Spec,
                "index" => MarkdownTemplate::Index,
                "command" => MarkdownTemplate::Command,
                "argument" => MarkdownTemplate::Argument,
                "flag" => MarkdownTemplate::Flag,
                "config" => MarkdownTemplate::Config,
                _ => usage::miette::bail!(
                    "unknown template `{name}`; expected spec, index, command, argument, flag, or config"
                ),
            };
            let path = PathBuf::from(path);
            let source = std::fs::read_to_string(&path)
                .map_err(|err| UsageErr::FileError(err, path.clone()))?;
            ctx = ctx.with_template(template, source);
        }
        if let Some(url_prefix) = &self.url_prefix {
            ctx = ctx.with_url_prefix(url_prefix);
        }
        if self.multi {
            ctx = ctx.with_multi(true);
            // Before anything is written, so a refusal does not leave a half-built directory.
            //
            // Refused rather than warned about: writing anyway destroys the command's own
            // documentation, and a warning printed into a docs build is a warning nobody reads.
            // No CLI in the fleet has a `configuration` command — they call it `config` — so
            // this asks the one author who ever hits it to pick a name, rather than quietly
            // losing a page for everybody who does not.
            if !ctx.render_config()?.trim().is_empty() {
                if let Some(cmd) = ctx.config_page_collision() {
                    usage::miette::bail!(
                        "the `{cmd}` command's page and the settings page would both be written \
                         to {}; rename the command, or hide it, to generate both",
                        ctx.config_page()
    #[serde(skip_serializing_if = "Option::is_none")]
    pub select: Option<String>,
    /// CLI-wide exit codes, refined per command rather than replaced.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub exit_codes: Vec<SpecExitCode>,
    /// Default subcommand to use when first non-flag argument is not a known subcommand.
    /// This enables "naked" command syntax like `mise foo` instead of `mise run foo`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_subcommand: Option<String>,
    /// Whether argv[0]'s basename selects a subcommand (busybox-style applets).
    ///
    /// clap's `multicall`. The dispatcher names ([`Self::name`] and [`Self::bin`])
    /// are skipped; any other basename is parsed as the first word, so a symlink
    /// `ls -> busybox` runs the `ls` applet. Path components and a trailing `.exe`
    /// are stripped.
    #[serde(default, skip_serializing_if = "is_false")]
    pub multicall: bool,
    /// Whether the source explicitly declared [`Self::multicall`].
    ///
    /// This distinguishes an omitted node from `multicall #false` while includes
    /// are merged. It is parsing bookkeeping rather than part of the JSON model.
    #[doc(hidden)]
    #[serde(skip)]
    pub multicall_set: bool,
    /// What to do with a flag-like token that names no declared flag, for the whole
    /// CLI. A command may override it; see [`SpecCommand::unknown_flags`].
    pub unknown_flags: Option<crate::spec::unknown_flags::UnknownFlags>,
}

impl Spec {
    /// Recompute everything a command's position in this tree decides, after building one by
    /// hand: each command's path, its usage line, and the memoized subcommand lookup.
    ///
    /// A `SpecCommand` inserted into `subcommands` carries the path it had wherever it came
    /// from — a spec of its own, most likely, where it was the root and its path was empty. Its
    /// help page would say so. So would its parent's, which gains a `<SUBCOMMAND>` placeholder
    /// the first time it acquires a child. Call this after grafting, and the tree is
    /// indistinguishable from one that declared the same commands in KDL.
    ///
    /// The alternative — writing the tree out and parsing it back, which is how this was reached
    /// before — costs a KDL round trip of the whole spec. For a large one that is a quarter of a
    /// second to fix up strings.
    pub fn restamp(&mut self) {
        restamp_paths(&mut self.cmd, &[], true);
    }

    /// Resolve every mount from supplied command outputs without spawning processes.
    ///
    /// This is intended for deterministic generators and conformance harnesses. The
    /// map is keyed by each mount's exact `run` declaration. Missing entries are an
    /// error, so injecting a partial view cannot silently execute the remainder.
    pub fn resolve_mount_outputs(
        &mut self,
        outputs: &HashMap<String, String>,
    ) -> Result<(), UsageErr> {
        self.resolve_mount_outputs_at_root(outputs, true)
    }

    pub(crate) fn resolve_mount_outputs_at_root(
        &mut self,
        outputs: &HashMap<String, String>,
        apply_default_subcommand: bool,
    ) -> Result<(), UsageErr> {
        fn resolve(
            cmd: &mut SpecCommand,
            outputs: &HashMap<String, String>,
            skip_mounts: bool,
        ) -> Result<(), UsageErr> {
            if !skip_mounts && !cmd.mounts.is_empty() {
                cmd.mount(&[], Some(outputs))?;
                cmd.mounts.clear();
            }
            for subcommand in cmd.subcommands.values_mut() {
                resolve(subcommand, outputs, false)?;
            }
            Ok(())
        }

        let default_outranks_root_mounts = apply_default_subcommand
            && self.default_subcommand.is_some()
            && !self.cmd.mounts.iter().any(|mount| mount.overrides_default);
        resolve(&mut self.cmd, outputs, default_outranks_root_mounts)?;
        self.cmd
            .validate_clause_flag_spellings()
            .map_err(UsageErr::InvalidSpec)
    }

