mod tests {
    use crate::docs::markdown::renderer::MarkdownRenderer;
    use crate::test::SPEC_KITCHEN_SINK;
    use crate::Spec;
    use insta::assert_snapshot;

    /// `--replace-pre-with-code-fences` reaches a command's long help on the single-file page.
    ///
    /// `MarkdownRenderer::new` used to render the whole docs model eagerly, before the builder
    /// methods that set the options ran, and rendering marks each item done so the later pass
    /// no-opped. The multi-page path hid this by re-deriving each page from the raw command it
    /// is handed; the single-file page renders the stored model, so for it the flag did
    /// nothing at all — the whole option was a no-op on `usage generate markdown` without
    /// `--multi`.
    #[test]
    fn a_command_s_long_help_gets_the_rendering_options_it_was_asked_for() {
        let src = "name \"v\"\nbin \"v\"\ncmd \"go\" help=\"Go\" long_help=\"Goes.\\n\\n    v go --now\\n\\nOk.\"\n";
        let spec: Spec = src.parse().unwrap();

        let with_fences = MarkdownRenderer::new(spec.clone())
            .with_indented_blocks_to_code_fences(true)
            .render_spec()
            .unwrap();
        assert!(
            with_fences.contains("```\nv go --now\n```"),
            "the option did not reach the command's help:\n{with_fences}"
        );

        // And without it the block stays indented, so the assertion above is about the option
        // rather than about something else in the pipeline.
        let without = MarkdownRenderer::new(spec).render_spec().unwrap();
        assert!(!without.contains("```"), "{without}");
        assert!(without.contains("    v go --now"), "{without}");
    }

    /// The former builder name still reaches the same option.
    ///
    /// It is kept, not renamed away, so an existing docs build keeps compiling; that only
    /// helps if it keeps working, which nothing else here would notice.
    #[test]
    fn the_former_builder_name_still_works() {
        let src = "name \"v\"\nbin \"v\"\ncmd \"go\" help=\"Go\" long_help=\"Goes.\\n\\n    v go --now\\n\\nOk.\"\n";
        let spec: Spec = src.parse().unwrap();
        let page = MarkdownRenderer::new(spec)
            .with_replace_pre_with_code_fences(true)
            .render_spec()
            .unwrap();
        assert!(page.contains("```\nv go --now\n```"), "{page}");
    }

    /// An option set after a render still applies, because the builders drop the rendered model.
    #[test]
    fn an_option_set_after_a_render_still_takes_effect() {
        let src = "name \"v\"\nbin \"v\"\ncmd \"go\" help=\"Go\" long_help=\"Goes.\\n\\n    v go --now\\n\\nOk.\"\n";
        let spec: Spec = src.parse().unwrap();

        let ctx = MarkdownRenderer::new(spec);
        assert!(!ctx.render_spec().unwrap().contains("```"));
        let ctx = ctx.with_indented_blocks_to_code_fences(true);
        assert!(
            ctx.render_spec().unwrap().contains("```\nv go --now\n```"),
            "a render before the builder froze the model"
        );
    }

    #[test]
    fn test_render_markdown_spec() {
        let ctx = MarkdownRenderer::new(SPEC_KITCHEN_SINK.clone());
        assert_snapshot!(ctx.render_spec().unwrap(), @"
        # `mycli`

        - **Usage:** `mycli [FLAGS] <ARGS>… <SUBCOMMAND>`

        ## Arguments
        - **`<arg1>`** — arg1 description
        - **`[arg2]`** — arg2 description

          **Choices:** `choice1`, `choice2`, `choice3`

          **Default:** `default value`
        - **`<arg3>`** — arg3 long description
        - **`<argrest>…`**
        - **`[with-default]`**

          **Default:** `default value`

        ## Flags
        - **`--flag1`** — flag1 description
        self.with(|r| r.theme = theme)
    }

    /// Replace one built-in Markdown template.
    ///
    /// Templates use [Tera](https://keats.github.io/tera/). A replacement may include any of the
    /// templates it did not replace; for example, a custom [`MarkdownTemplate::Spec`] can still
    /// contain `{% include "cmd_template.md.tera" %}`. Replacing the same member more than once
    /// uses the last value. Syntax and include errors are returned by the render method.
    pub fn with_template(self, template: MarkdownTemplate, source: impl Into<String>) -> Self {
        let source = source.into();
        self.with(|r| {
            if let Some((_, current)) = r
                .templates
                .iter_mut()
                .find(|(current, _)| *current == template)
            {
                *current = source;
            } else {
                r.templates.push((template, source));
            }
        })
    }

    fn tera_ctx(&self) -> tera::Context {
        let mut ctx = tera::Context::new();
        ctx.insert("spec", self.spec());
        ctx.insert("header_level", &self.header_level);
        ctx.insert("multi", &self.multi);
        ctx.insert("url_prefix", &self.url_prefix);
        ctx.insert("html_encode", &self.html_encode);
        ctx
    }

    /// Render with values that belong only to this page.
    ///
    /// A page used to clone the whole renderer — including the complete command tree — merely
    /// to insert one local into its stored context. Multi-page output paid that deep clone once
    /// per command. The context already has to be materialized for Tera, so enrich that directly.
    pub(crate) fn render_with(
        &self,
        template_name: &str,
        enrich: impl FnOnce(&mut tera::Context),
    ) -> Result<String, UsageErr> {
        let mut tera = match self.theme {
            MarkdownTheme::Compact => TERA.clone(),
            MarkdownTheme::Detailed => crate::docs::markdown::tera::DETAILED_TERA.clone(),
        };

        for (template, source) in &self.templates {
            tera.add_raw_template(template.name(), source)?;
        }

        let html_encode = self.html_encode;
        tera.register_filter(
            "escape_md",
            move |value: &tera::Value,
                  _: tera::Kwargs,
                  _: &tera::State|
                  -> tera::TeraResult<String> {
                let value = value.as_str().unwrap();
                let value = escape_md(value, html_encode);
                Ok(value)
            },
        );
        tera.register_filter(
            "escape_md_indented",
            move |value: &tera::Value,
                  _: tera::Kwargs,
                  _: &tera::State|
                  -> tera::TeraResult<String> {
                let value = value.as_str().unwrap();
                Ok(escape_md_with_indent(value, html_encode, true))
            },
        );

        let mut ctx = self.tera_ctx();
        enrich(&mut ctx);
        Ok(tera.render(template_name, &ctx)?)
    }

    /// Rewrite four-space indented blocks as fenced ones, when the caller asked for it.
    pub(crate) fn fence_indented_blocks(&self, md: String) -> String {
        if !self.indented_blocks_to_code_fences {
            return md;
        }
        // TODO: handle fences inside of <pre> or <code>
        let mut in_code_block = false;
        let mut new_md = String::new();
        for line in md.lines() {
            if let Some(line) = line.strip_prefix("    ") {
                if in_code_block {
                    new_md.push_str(&format!("{line}\n"));
                } else {
                    new_md.push_str(&format!("```\n{line}\n"));
                    in_code_block = true;
                }
            } else {
                if in_code_block {
                    new_md.push_str("```\n");
                    in_code_block = false;
                }
                new_md.push_str(&format!("{line}\n"));
            }
        }
        if in_code_block {
            new_md.push_str("```\n");
        }
        new_md.replace("```\n\n```\n", "\n")
    }
}

