const fs = require('fs');
const cp = require('child_process');
const root = '/tmp/mise-structured-examples';
const files = cp.execFileSync('rg', ['--files', 'src/cli'], {cwd:root,encoding:'utf8'}).trim().split('\n').filter(f=>f.endsWith('.rs'));
const pattern = /(?:static|const) (\w+): &str = color_print::cstr!\(\s*r#"([\s\S]*?)"#\s*\);/g;
const heading = '<bold><underline>Examples:</underline></bold>';
const raw = text => 'r###"' + text + '"###';
let patch = '*** Begin Patch\n';
let count = 0;
for (const file of files) {
 const original = fs.readFileSync(root+'/'+file,'utf8');
 let corrected;
 try { corrected = cp.execFileSync('git',['show','636e6246a91a47c06f35ae6c82c7f8c8bbf5345a:'+file],{cwd:root,encoding:'utf8',stdio:['ignore','pipe','ignore']}); } catch { corrected = original; }
 const corrections = new Map([...corrected.matchAll(pattern)].map(m=>[m[1],m[2]]));
 let updated = original;
 for (const match of original.matchAll(pattern)) {
  const name = match[1];
  const attr = new RegExp('after_long_help\\s*=\\s*'+name+'\\b');
  if (!attr.test(updated) || !match[2].includes(heading)) continue;
  const content = corrections.get(name) ?? match[2];
  if (!content.includes(heading)) continue;
  const [before, examples] = content.split(heading);
  const lines = examples.replace(/<\/?(?:bold|underline|dim|italic|cyan|yellow|green|red)>/g,'').split('\n');
  if (lines.some(line=>line.trim() && !line.startsWith('    '))) { console.error('manual '+file+' '+name); continue; }
  const blocks = lines.map(l=>l.startsWith('    ')?l.slice(4):l).join('\n').trim().split(/\n\s*\n(?=#[^!]|\$ )/);
  const declarations = blocks.filter(Boolean).map(block=> {
   const lines=block.split('\n'); const help=[];
   while(lines[0]?.startsWith('# ')) help.push(lines.shift().slice(2));
   const code=lines.join('\n').replace(/^\$ /gm,'').trim();
   return 'example('+raw(code)+(help.length?', help = '+raw(help.join('\n')):'')+')';
  });
  updated = updated.replace(attr, (before.trim()?'after_long_help = '+name+',\n    ':'')+declarations.join(',\n    '));
  updated = updated.replace(match[0], before.trim()? 'static '+name+': &str = color_print::cstr!('+raw(before.trim())+');':'');
  count += declarations.length;
 }
 if(updated!==original) patch += '*** Update File: '+root+'/'+file+'\n@@\n'+original.trimEnd().split('\n').map(l=>'-'+l).join('\n')+'\n'+updated.trimEnd().split('\n').map(l=>'+'+l).join('\n')+'\n';
}
console.error('examples '+count);
process.stdout.write(patch+'*** End Patch\n');

