+            .get_matches()
+            .into_iter()
+            .map(|(short, description)| vec![short, description])
+            .collect_vec();
+        if tools.is_empty() {
+            bail!("tool {} not found in registry", self.name.as_ref().unwrap());
+        }
+
+        let mut table = MiseTable::new(self.no_header, &["Tool", "Description"]);
+        for row in tools {
+            table.add_row(row);
