+/// Operates on the lockfile in the current config root. Use TOOL arguments to target specific tools.
+#[derive(Debug, usage_rs::Args)]
+#[usage(verbatim_doc_comment, example(r###"mise lock                       # create or refresh the project lockfile
+mise lock node python           # update only node and python
+mise lock --platform linux-x64  # update only linux-x64 platform
+mise lock --dry-run             # show what would be updated
+mise lock --bump                # re-resolve selectors like "latest" or "20" to the latest matching versions
+mise lock --bump --dry-run --json   # list available updates as JSON without writing
+mise lock --minimum-release-age 2024-01-01   # lock latest/fuzzy versions released before 2024-01-01
+mise lock --local               # update mise.local.lock for local configs
+mise lock --global              # update only global config lockfiles"###))]
+pub(crate) struct Lock {
+    /// Tool(s) to update in lockfile
+    /// e.g.: node python
+    /// If not specified, all configured and task-specific tools will be updated
+    #[usage(value_name = "TOOL", verbatim_doc_comment)]
+    pub tool: Vec<ToolArg>,
+
+    /// Target only global config lockfiles (~/.config/mise/mise.lock and system config)
+    /// By default, only the active project config root is locked
+    #[usage(long, short, verbatim_doc_comment)]
+    pub global: bool,
+
+    /// Number of jobs to run in parallel
+    /// Values below 1 are treated as 1
+    #[usage(long, short, env = "MISE_JOBS", verbatim_doc_comment)]
+    pub jobs: Option<usize>,
+
+    /// Show what would be updated without making changes
+    #[usage(long, short = 'n', verbatim_doc_comment)]
+    pub dry_run: bool,
+
+    /// Comma-separated list of platforms to target
+    /// e.g.: linux-x64,macos-arm64,windows-x64
+    /// If not specified, all platforms already in lockfile will be updated
+    #[usage(long, short, delimiter = ',', verbatim_doc_comment)]
+    pub platform: Vec<String>,
+
+    /// Re-resolve fuzzy version selectors against the latest available versions
+    ///
+    /// By default, `mise lock` refreshes metadata for the currently locked versions.
+    /// With this flag, selectors like "latest", "lts", or prefixes like "20" are
+    /// re-resolved against the latest matching remote versions, so the lockfile
+    /// advances without installing anything. Config files are never modified:
+    /// exactly pinned versions resolve to themselves and stay unchanged
+    /// (use `mise upgrade --bump` to rewrite pins in mise.toml).
+    #[usage(long, verbatim_doc_comment)]
+    pub bump: bool,
+
+    /// Output version changes as JSON
+    ///
+    /// Prints an array of objects describing lockfile version changes:
+    /// name, backend, lockfile, old_versions, new_versions.
+    /// Version lists keep config/lockfile order; they are not sorted.
+    /// Only version-level changes are reported: checksum/URL refreshes for
+    /// unchanged versions produce no entries, so plain `mise lock --json`
+    /// typically prints `[]` while still updating the lockfile.
+    /// Suppresses the human-readable output. Combine with `--dry-run` to
+    /// detect available updates without writing the lockfile.
+    #[usage(long, verbatim_doc_comment)]
+    pub json: bool,
+
+    /// Update mise.local.lock instead of mise.lock
+    /// Use for tools defined in .local.toml configs
+    #[usage(long, verbatim_doc_comment)]
+    pub local: bool,
+
+    /// Only lock versions released before this age or date
+    ///
+    /// Supports absolute dates like "2024-06-01" and relative durations like "90d" or "1y".
+    /// This only affects fuzzy version matches like "20" or "latest".
+    /// Explicitly pinned versions like "22.5.0" are not filtered.
+    /// Existing matching lockfile entries are preserved and are not downgraded solely by this flag.
+    #[usage(
+        long,
+        alias = "before",
+        value_name = "MINIMUM_RELEASE_AGE",
+        verbatim_doc_comment
+    )]
+    pub minimum_release_age: Option<String>,
+
+    /// Upgrade legacy lockfiles to the latest format
+    ///
+    /// Existing unversioned lockfiles use format version 0 and are otherwise
+    /// preserved to avoid unexpected lockfile drift. This flag upgrades them
+    /// to the latest format with request-specific version bindings.
+    /// Format upgrades always process every configured tool and cannot be
+    /// combined with tool arguments.
+    #[usage(long, verbatim_doc_comment)]
+    pub upgrade: bool,
+}
+
+/// A lockfile version change reported by `--json`
+#[derive(serde::Serialize)]
+struct LockChange {
+    name: String,
+    backend: Option<String>,
+    lockfile: String,
+    old_versions: Vec<String>,
+    new_versions: Vec<String>,
+}
+
+struct LockTaskResult {
+    short: String,
+    version: String,
+    platform: String,
+    status: LockTaskStatus,
+}
+
+struct StagedUpgradeWrite {
+    path: PathBuf,
+    original_content: Option<Vec<u8>>,
+    lockfile: Lockfile,
+    summary: Option<(usize, usize)>,
+    format_changed: bool,
+    stale_tools: BTreeSet<String>,
+    stale_versions: BTreeMap<String, Vec<String>>,
+}
+
+struct LockfileSnapshot {
+    path: PathBuf,
+    content: Option<Vec<u8>>,
+}
+
+struct PreparedLockfileRollback {
+    path: PathBuf,
+    replacement: Option<crate::file::PreparedAtomicWrite>,
+}
+
+fn read_optional_file(path: &Path) -> Result<Option<Vec<u8>>> {
+    match fs::read(path) {
+        Ok(content) => Ok(Some(content)),
+        Err(err) if err.kind() == ErrorKind::NotFound => Ok(None),
+        Err(err) => Err(err.into()),
+    }
+}
+
+fn prepare_lockfile_rollback(
+    snapshots: &[LockfileSnapshot],
+) -> Result<Vec<PreparedLockfileRollback>> {
+    snapshots
+        .iter()
+        .map(|snapshot| {
+            let replacement = snapshot
+                .content
+                .as_ref()
+                .map(|content| crate::file::prepare_atomic_write(&snapshot.path, content))
+                .transpose()?;
+            Ok(PreparedLockfileRollback {
+                path: snapshot.path.clone(),
+                replacement,
+            })
+        })
+        .collect()
+}
+
+fn restore_lockfile_snapshots(rollbacks: Vec<PreparedLockfileRollback>) -> Result<()> {
+    let mut errors = Vec::new();
+    for rollback in rollbacks.into_iter().rev() {
+        let result = match rollback.replacement {
+            Some(replacement) => replacement.commit(),
+            None => match fs::remove_file(&rollback.path) {
+                Ok(()) => Ok(()),
+                Err(err) if err.kind() == ErrorKind::NotFound => Ok(()),
+                Err(err) => Err(err.into()),
+            },
+        };
+        if let Err(err) = result {
+            errors.push(format!("{}: {err:?}", display_path(&rollback.path)));
+        }
+    }
+    lockfile::invalidate_caches();
+    if errors.is_empty() {
+        Ok(())
+    } else {
+        bail!("{}", errors.join("\n"))
+    }
+}
+
+#[derive(Debug, Eq, PartialEq)]
+enum LockTaskStatus {
+    Updated,
+    Unresolved,
+    Failed,
+    ProvenanceFailed,
+}
+
+fn classify_lock_result(
+    resolution_error: Option<String>,
+    error_is_fatal: bool,
+    applied: bool,
+) -> (LockTaskStatus, Option<String>) {
+    if let Some(error) = resolution_error.filter(|_| error_is_fatal) {
+        (LockTaskStatus::Failed, Some(error))
+    } else if applied {
+        (LockTaskStatus::Updated, None)
+    } else {
+        (LockTaskStatus::Unresolved, None)
+    }
+}
