+                let start = std::time::Instant::now();
+                let result = match self
+                    .test(
+                        &config,
+                        &target.tool,
+                        &target.cmd,
+                        &target.expected,
+                        &target.tools,
+                    )
+                    .await
+                {
+                    Ok(output) => TestToolResult {
+                        index: target.index,
+                        tool,
+                        duration: start.elapsed(),
+                        output,
+                        error: None,
+                        status_logged: false,
+                    },
+                    Err(err) => TestToolResult {
+                        index: target.index,
