+        let resolve_options = if has_explicit_latest {
+            ResolveOptions {
+                latest_versions: true,
+                use_locked_version: false,
+                ..Default::default()
+            }
+        } else {
+            Default::default()
+        };
+
+        let ts = measure!("toolset", {
+            ToolsetBuilder::new()
+                .with_args(&self.tool)
+                .with_default_to_latest(true)
+                .with_resolve_options(resolve_options.clone())
+                .build(&config)
+                .await?
+        });
+
+        self.run_with_context(
+            config,
+            ts,
+            resolve_options,
+            has_explicit_latest,
+            BTreeMap::new(),
+            false,
+        )
+        .await
+    }
+
