+        self,
+        config: Arc<Config>,
+        ts: Toolset,
+        wrapper_env: BTreeMap<String, String>,
+    ) -> eyre::Result<()> {
+        self.run_with_context(
+            config,
+            ts,
+            ResolveOptions::default(),
+            false,
+            wrapper_env,
+            true,
+        )
+        .await
+    }
