+
+/// Disable mise for current shell session
+///
+/// This can be used to temporarily disable mise in a shell session.
+#[derive(Debug, usage_rs::Args)]
+#[usage(verbatim_doc_comment, example(r###"eval "$(command mise deactivate)""###, help = r###"Bash or Zsh, calling the executable rather than the activation function"###),
