+        let mut prefix = tv.style();
+        if dry_run {
+            prefix = format!("{} {} ", prefix, style("[dryrun]").bold());
+        }
+        if !dry_run
+            && !Settings::get().yes
+            && !prompt::confirm_with_all(format!("remove {} ?", tv))?.is_yes()
+        {
