+impl TestTool {
+    pub(crate) async fn run(self) -> Result<()> {
+        // Registry validation must exercise new releases immediately, including
+        // the first release supported by a newly added backend.
+        Settings::override_with(|s| s.minimum_release_age = Some("0".to_string()));
+        let mut errored = vec![];
+        self.github_summary(vec![
+            "Tool".to_string(),
+            "Duration".to_string(),
+            "Status".to_string(),
+        ])?;
+        self.github_summary(vec![
+            "---".to_string(),
+            "---".to_string(),
+            "---".to_string(),
+        ])?;
+        let mut config = Config::get().await?;
+
+        let target_tools = self.get_target_tools(&config).await?;
+        let mut targets = vec![];
+        for (i, (tool, rt)) in target_tools.into_iter().enumerate() {
+            if !should_test_registry_tool(rt) {
+                continue;
+            }
+            if *env::TEST_TRANCHE_COUNT > 0 && (i % *env::TEST_TRANCHE_COUNT) != *env::TEST_TRANCHE
+            {
+                continue;
+            }
+            let (cmd, expected, tools) = if let Some(test) = rt.test.as_ref() {
+                (
+                    test.cmd.to_string(),
+                    test.expected.to_string(),
+                    test.tools.iter().map(|tool| tool.to_string()).collect(),
+                )
+            } else if self.include_non_defined {
+                (
+                    format!("{} --version", tool.short),
+                    "__TODO__".to_string(),
+                    vec![],
+                )
+            } else {
+                continue;
+            };
+            targets.push(TestToolTarget {
+                index: targets.len(),
+                tool,
+                cmd,
+                expected,
+                tools,
+            });
+        }
