+    example(r###"mise exec node@20 python@3.11 --command "node -v && python -V""###, help = r###"Specify command as a string:"###),
+    example(r###"mise x -C /path/to/project node@20 -- node ./app.js"###, help = r###"Run a command in a different directory:"###))]
