+fn parse_command(
+    shell: &str,
+    command: &Option<Vec<String>>,
+    c: &Option<String>,
+) -> (String, Vec<String>) {
+    match (&command, &c) {
+        (Some(command), _) => {
+            let (program, args) = command.split_first().unwrap();
+            (program.clone(), args.into())
+        }
+        _ => (
+            shell.into(),
+            vec![env::SHELL_COMMAND_FLAG.into(), c.clone().unwrap()],
+        ),
+    }
