+            if !self.sources.is_empty() {
+                lines.push("#MISE sources=[\"".to_string() + &self.sources.join("\", \"") + "\"]");
+            }
+            if !self.outputs.is_empty() {
+                lines.push("#MISE outputs=[\"".to_string() + &self.outputs.join("\", \"") + "\"]");
+            }
+            if self.quiet {
