-            None
-        },
-        install_path,
-        version: tv.version.clone(),
-        requested_version: if all_sources || source.is_unknown() {
-            None
-        } else {
-            Some(tv.request.version())
-        },
-        source: if all_sources || source.is_unknown() {
-            None
-        } else {
-            Some(source.as_json())
-        },
-        sources: if all_sources { sources } else { None },
