+            }
+            if let Some(tools) = filter_tools
+                && !tools.iter().any(|t| t.ba.as_ref() == tv.ba())
+            {
+                continue;
+            }
+            let warning_key = format!("{}@{}", tv.ba().short, tv.request.version());
+            if !warned.insert(warning_key) {
+                continue;
+            }
