+                (None, Some(baseline)) => {
+                    if current_satisfies_hidden_release(config, &tv, &baseline) {
+                        continue;
+                    }
+                    warn_hidden_release_ignored_by_minimum_release_age(
+                        config,
+                        &tv,
+                        &baseline,
+                        age.as_deref(),
+                        "no eligible release found",
