+impl SettingsLs {
+    pub(super) fn run(self) -> Result<()> {
+        if self.complete {
+            return self.complete();
+        }
+        let mut rows: Vec<Row> = if self.local {
+            let source = config::local_toml_config_path();
+            let partial = Settings::parse_settings_file(&source).unwrap_or_default();
